import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易尚氏學 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易尚氏學 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"classics/shangshi/016.md","filePath":"classics/shangshi/016.md"}'),s={name:"classics/shangshi/016.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>陽性上升。陰性下降。乃陰在上。陽在下。故其氣相接相交而為泰。泰通也。陽大陰小。爻在外曰往。在內曰來。故曰小往大來。泰寅月卦。陽長故亨。</p><p>彖曰。泰。小往大來吉亨。則是天地交而萬物通也。上下交而其志同也。內陽而外陰。內健而外順。內君子而外小人。君子道長。小人道消也。</p><p>陽上升。陰下降。故氣交。坤為萬物。為心志。交則萬物氣通。心志和合，故曰同。坤志象失傳。易林屯之益雲。心勞且憂。益互坤。以坤為心。又需之否雲。毛羽憔悴。志如死灰。以否下坤為志為死。(詳焦氏易詁易象補遺)內陽外陰。內健外順。內君子外小人。將老氏宗旨。括盡無餘。乾為君子。坤為小人。泰本候卦。陽長故陰消。按上經始乾坤。終水火。而以否泰為樞紐。明否泰剝復。皆天地自然之法象。循環之原理。君子所宜居而安也。靜之象也。下經始鹹恆。終既未濟。而以損益。為樞紐。明吉凶失得。進退變化。全在人為。君子所以自強不息也。動之象也。而否泰損益。皆序於第十卦後者。數至十則盈。盈則變也。</p><p>象曰。天地交。泰。後以財成天地之道。輔相天地之宜。以左右民。</p><p>財裁同。釋文荀作裁。釋言疏。財裁音義並同。漢時臣工上疏。裁察每作財察。是其證。財成即裁成也。互震為左。互兌為右。坤為民。以左右民者。孔疏左右助也。以助養其民也。虞翻謂坤富稱財非。</p><p>初九。拔茅茹。以其匯。徵吉。</p><p>初應在四。四坤為茅茹。此象失傳。易林剝之坤雲。荻芝俱死。以坤為荻芝。又同人之屯雲。蓬蒿代柱。大屋顛倒。屯互艮為屋為柱。互坤為蓬蒿。故坤亦為茅茹。茹菜屬也。詩鄭風茹藘在阪。前漢食貨志。菜茹有畦。茅。說文菅也。茹與茅為二物。以其匯者。言茅與茹同拔。連類以及也。四有應。故徵吉。</p><h3 id="象曰。拔茅徵吉。志在外也。" tabindex="-1">象曰。拔茅徵吉。志在外也。 <a class="header-anchor" href="#象曰。拔茅徵吉。志在外也。" aria-label="Permalink to “象曰。拔茅徵吉。志在外也。”">​</a></h3><p>初應在四。故曰志在外。外坤為心志。</p><p>九二。苞荒。用馮河。不遐遺。朋亡。得尚於中行。</p><p>釋文雲。荒本亦作巟。說文引同。許雲水廣。虞雲大川也。晁氏雲。漢易皆作巟彖辭巟河是一事。象數無田穢之荒。作荒始於王弼。按晁說是也。巟河為對文。王弼蓋以坤為亂。改作荒。豈知坤為水。巟與河皆坤象也。苞今本作包。唐石經增改作苞。釋文亦作苞。二應在五。五坤為大川。為河。言二必上升。有苞括大川。馮涉長河之勢。斷不以其遼遠而不及也。陰以陽為朋。亡往也去也。朋往者。言二必往五。得尚居中正之位也。舊詁因坤水象及朋義失傳。故無有得解者。(禮記少儀有亡而無疾。晉語請從此亡。注皆訓為去。)</p><h3 id="象曰。苞荒。得尚於中行。以光大也。" tabindex="-1">象曰。苞荒。得尚於中行。以光大也。 <a class="header-anchor" href="#象曰。苞荒。得尚於中行。以光大也。" aria-label="Permalink to “象曰。苞荒。得尚於中行。以光大也。”">​</a></h3><p>五位尊。故曰光大。</p><p>九三。無平不陂。無往不復。艱貞無咎。勿恤其孚。於食有福。</p><p>陂傾也。復返也。陽息至三天地分。故曰平。然三居卦終。乾三雲。終日乾乾。反覆道也。言陽至三而盈。將反初成巽也。故曰無平不陂。無往不復。(巽隕落故傾)平陂往復。雖相循環。然三本當位。能艱貞自守。必無咎也。坤為憂恤。(臨六三雲。既憂之無咎。以坤為憂。易林大壯之損雲。使母憂嘆。以損互坤為憂也。詳焦氏易詁。)三臨之孚於群陰。故無恤。兌口為食。坤多故曰於食有福。乾為福也。</p><h3 id="象曰。無往不復。天地際也。" tabindex="-1">象曰。無往不復。天地際也。 <a class="header-anchor" href="#象曰。無往不復。天地際也。" aria-label="Permalink to “象曰。無往不復。天地際也。”">​</a></h3><p>廣韻際邊也。畔也。三應在上。三上居天地之極。極則返始。釋平必陂。往必復之故也。宋衷曰。三位在乾極。應在坤極。以極詁際字。最為明晰。乃惠棟李道平等解釋宋注。竟從小爾雅謂際者接也。天地際。即天地交接也。豈知乾極坤極，正釋際義。際若為交接。與無往不復之義何與哉。失宋義矣。其它更無有能得解者。易理之失傳。更甚於易象矣。</p><p>六四。翩翩。不富。以其鄰不戒以孚。</p><p>震為飛。故曰翩翩。坤虛。故曰不富。以與也。震為鄰。以其鄰不戒以孚者。言四及五上。皆有應予。下孚於陽也。陰得陽應必吉。故曰不戒以孚。戒告誡也。震飛之象。易林屢用之。同人之坎雲。出於幽谷。飛上喬木。以坎互震為飛也。證之易明夷初九雲。明夷于飛。易即以震為飛。舊解以離為飛。若泰無離象也。</p><h3 id="象曰。翩翩不富。皆失實也。不戒以孚。中心願也。" tabindex="-1">象曰。翩翩不富。皆失實也。不戒以孚。中心願也。 <a class="header-anchor" href="#象曰。翩翩不富。皆失實也。不戒以孚。中心願也。" aria-label="Permalink to “象曰。翩翩不富。皆失實也。不戒以孚。中心願也。”">​</a></h3><p>坤為心志。(按益九五雲有孚惠心。以互坤為心也。否初象雲志在君也。以坤為志也。易林以坤為心志。證尤多。舊解皆以坎為心志。自得此象。凡易言心志者。始皆得解。)中心願者。言陰喜應陽也。陽為實。失實。言無陽。</p><p>六五。帝乙歸妹。以祉元吉。</p><p>震為帝。坤貞乙。故曰帝乙。兌為妹。震為歸。婦人謂嫁曰歸。歸妹謂嫁妹也。正中爻震兌象也。祉福也。以祉元吉者。言二升五。五來二。(來二即歸)各當其位。永為儷耦。故元吉也。象釋曰中以行願。即謂五願歸居二也。帝乙或謂為成湯。或謂為紂父。</p><h3 id="象曰。以祉元吉。中以行願也。" tabindex="-1">象曰。以祉元吉。中以行願也。 <a class="header-anchor" href="#象曰。以祉元吉。中以行願也。" aria-label="Permalink to “象曰。以祉元吉。中以行願也。”">​</a></h3><p>五位尊。故曰元吉。中以行願。即謂五願歸二也。</p><p>上六。城復於隍。勿用師。自邑告命。</p><p>貞吝。復覆通。詩陶復陶穴。說文引作覆。是其證。艮為城。兌為隍。城池也。三至上艮覆。正當兌澤。故曰城覆於隍。九家雲。城覆於隍。國政崩也。崩即謂艮覆。京房於復卦。朋來無咎。朋作崩。與此義同也。又易林歸妹之泰雲。傾奪我城。使家不寧。城傾。即謂泰三至上艮覆。釋此爻也。坤為師。震為言。為告命。坤陰下降主退。故曰勿用。吳先生曰。邑挹之省文。挹損也。言自挹損其告命。如復世之下詔罪己也。貞吝。言卜問不吉。泰極將返否故也。</p><h3 id="象曰。城復於隍。其命亂也。" tabindex="-1">象曰。城復於隍。其命亂也。 <a class="header-anchor" href="#象曰。城復於隍。其命亂也。" aria-label="Permalink to “象曰。城復於隍。其命亂也。”">​</a></h3><p>坤為亂。其命亂者。言泰極返否。為天地自然之命運。無可避免。此命字與告命異。諸家混同之。非。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
